import { Link, useLocation, useNavigate } from "react-router-dom";
import { FaUserCircle } from "react-icons/fa";
import { API } from "../api/api";
import { useEffect, useState } from "react";

export default function Navbar() {
  const location = useLocation();
  const nav = useNavigate();

  const [user, setUser] = useState(null);

  useEffect(() => {
    API.get("/auth/verify")
      .then(res => setUser(res.data.user))
      .catch(() => setUser(null));
  }, []);

  const logout = async () => {
    await API.post("/auth/logout");
    nav("/");
  };

  return (
    <nav style={styles.navbar}>
      
      {/* LOGO */}
      <h2 style={styles.logo} onClick={() => nav("/home")}>
        PollHub 🚀
      </h2>

      {/* LINKS */}
      <div style={styles.links}>
        <Link to="/home" style={styles.link}>
          <span style={location.pathname === "/home" ? styles.active : null}>
            Home
          </span>
        </Link>

        <Link to="/create-poll" style={styles.link}>
          <span style={location.pathname === "/create-poll" ? styles.active : null}>
            Create Poll
          </span>
        </Link>

        <Link to="/create-survey" style={styles.link}>
          <span style={location.pathname === "/create-survey" ? styles.active : null}>
            Create Survey
          </span>
        </Link>
      </div>

      {/* PROFILE */}
       <button
        style={styles.logout}
        onClick={async () => {
          await fetch("http://localhost:5001/api/auth/logout", {
            method: "POST",
            credentials: "include"
          });
          nav("/");
        }}
      >
        Logout
      </button>

    </nav>
    
  );
}
const styles = {
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "14px 28px",
    background: "#111827",
    color: "#fff",
  },

  logo: {
    margin: 0,
    fontSize: "22px",
    fontWeight: "bold",
    cursor: "pointer",
  },

  links: {
    display: "flex",
    gap: "20px",
  },

  link: {
    textDecoration: "none",
    color: "#cbd5e1",
  },

  active: {
    color: "#3b82f6",
    borderBottom: "2px solid #3b82f6",
  },

  logout: {
    padding: "6px 12px",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    background: "#ef4444",
    color: "white",
  }
};
